import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const html=fs.readFileSync(new URL('../arcade.html',import.meta.url),'utf8');
const source=[...html.matchAll(/<script\b[^>]*>([\s\S]*?)<\/script>/gi)][0][1];
function fixture(){const context=vm.createContext({});vm.runInContext(source+'\nglobalThis.Engine=Afterglow;',context);const g=new context.Engine(()=>.42);g.start();return g;}
const piece=(kind,m,x,y)=>({kind,m,x,y});
test('seven-bag distribution and independent board rows',()=>{const g=fixture();const first=[g.piece.kind,...g.queue.slice(0,6)];assert.equal(new Set(first).size,7);g.board[0][0]='T';assert.equal(g.board[1][0],null);assert.equal(g.board.length,20);assert.ok(g.queue.length>=7);});
test('movement respects both walls and occupied cells',()=>{const g=fixture();g.piece=piece('O',[[1,1],[1,1]],0,5);assert.equal(g.move(-1),false);assert.equal(g.piece.x,0);g.board[5][2]='T';assert.equal(g.move(1),false);g.board[5][2]=null;assert.equal(g.move(1),true);g.piece.x=8;assert.equal(g.move(1),false);});
test('rotation cycles, inverse rotation and a wall kick',()=>{const g=fixture();g.spawn('T');const original=JSON.stringify(g.piece.m);for(let i=0;i<4;i++)assert.equal(g.rotate(),true);assert.equal(JSON.stringify(g.piece.m),original);g.rotate();g.rotate(-1);assert.equal(JSON.stringify(g.piece.m),original);g.spawn('I');g.rotate();g.piece.x=-2;assert.equal(g.fits(g.piece),true);assert.equal(g.rotate(),true);assert.equal(g.fits(g.piece),true);assert.ok(g.piece.x>=0);});
test('gravity, soft drop and hard drop scoring',()=>{const g=fixture();g.spawn('O');g.tick(800);assert.equal(g.piece.y,1);assert.equal(g.score,0);g.move(0,1);assert.equal(g.piece.y,2);assert.equal(g.score,1);assert.equal(g.ghostY(),18);g.hardDrop();assert.equal(g.score,33);assert.equal(g.board[19].filter(Boolean).length,2);assert.equal(g.board[18].filter(Boolean).length,2);});
test('hold is limited to once per piece and restores spawn orientation',()=>{const g=fixture();g.spawn('T');g.rotate();assert.equal(g.hold(),true);assert.equal(g.held,'T');const next=g.piece.kind;assert.equal(g.hold(),false);g.hardDrop();assert.equal(g.hold(),true);assert.equal(g.piece.kind,'T');assert.equal(JSON.stringify(g.piece.m),'[[0,1,0],[1,1,1],[0,0,0]]');assert.notEqual(next,undefined);assert.equal(g.canHold,false);});
function fourRows(g){g.board=g.empty();for(let y=16;y<20;y++)g.board[y]=Array.from({length:10},(_,x)=>x===4?null:'J');g.piece=piece('I',[[1],[1],[1],[1]],4,16);g.lock();}
test('four-row clear, compaction, combo, level and event data',()=>{const g=fixture();const events=[];g.onEvent=e=>events.push(e);fourRows(g);assert.equal(g.score,800);assert.equal(g.lines,4);assert.equal(g.board.flat().filter(Boolean).length,0);assert.equal(events[0].rows.length,4);fourRows(g);assert.equal(g.score,1650);assert.equal(g.combo,1);fourRows(g);assert.equal(g.lines,12);assert.equal(g.level,2);assert.equal(g.score,2550);g.hardDrop();assert.equal(g.combo,-1);});
test('cleared rows shift surviving cells downward',()=>{const g=fixture();g.board[18][0]='Z';g.board[19]=Array.from({length:10},(_,x)=>x>=8?null:'J');g.piece=piece('O',[[1,1],[1,1]],8,18);g.lock();assert.equal(g.lines,1);assert.equal(g.score,100);assert.equal(g.board[19][0],'Z');assert.equal(g.board[19][8],'O');assert.ok(g.board[0].every(v=>v===null));});
test('lock delay and bounded reset prevent instant lock and infinite stalling',()=>{const g=fixture();g.spawn('O');g.piece.y=18;g.tick(400);assert.equal(g.board.flat().filter(Boolean).length,0);g.move(-1);assert.equal(g.lockTime,0);for(let i=0;i<14;i++)g.move(i%2? -1:1);assert.equal(g.resets,15);g.tick(400);g.move(1);assert.equal(g.lockTime,400);g.tick(50);assert.equal(g.board.flat().filter(Boolean).length,4);});
test('pause freezes board, scores, movement, rotation, hold and drop',()=>{const g=fixture();g.pause();const before=JSON.stringify(g);g.tick(5000);g.move(1);g.rotate();g.hold();g.hardDrop();assert.equal(JSON.stringify(g),before);g.pause();assert.equal(g.state,'playing');g.tick(800);assert.equal(g.piece.y,1);});
test('blocked spawn and above-board lock end the game',()=>{const g=fixture();g.board[0].fill('J');g.spawn('O');assert.equal(g.state,'over');g.start();g.piece=piece('O',[[1,1],[1,1]],4,-1);g.lock();assert.equal(g.state,'over');});
test('restart resets a completed or paused round',()=>{const g=fixture();fourRows(g);g.hold();g.pause();g.start();assert.equal(g.state,'playing');assert.equal(g.score,0);assert.equal(g.lines,0);assert.equal(g.level,1);assert.equal(g.held,null);assert.equal(g.canHold,true);assert.ok(g.board.flat().every(v=>v===null));assert.ok(g.piece);});
test('long deterministic play remains within legal board bounds',()=>{const g=fixture();for(let i=0;i<500;i++){if(g.state==='over')g.start();for(let j=0;j<i%6;j++)g.rotate(i%2?1:-1);for(let j=0;j<i%5;j++)g.move(i%2?1:-1);if(i%4===0)g.hold();assert.ok(g.fits(g.piece)||g.state==='over');g.hardDrop();assert.equal(g.board.length,20);assert.ok(g.board.every(r=>r.length===10));assert.ok(Number.isFinite(g.score));}});
test('delivery contains no external resources or network APIs',()=>{assert.doesNotMatch(html,/<(?:script|link|img|iframe|audio|video)\b[^>]*(?:src|href)\s*=/i);assert.doesNotMatch(html,/\b(?:fetch|XMLHttpRequest|WebSocket|importScripts)\s*\(/);assert.doesNotMatch(html,/url\(\s*['"]?https?:/i);});

