test('game-over overlay offers a working new round even without local storage',()=>{const s=setup();s.element('play').click();s.run("game.score=800;game.over();sync()");assert.equal(s.element('overlay').hidden,false);assert.match(s.element('overlayText').innerHTML,/800 points/);assert.equal(s.element('best').textContent,'800');s.element('play').click();assert.equal(s.run('game.state'),'playing');assert.equal(s.run('game.score'),0);assert.equal(s.run('best'),800);});
